"""Generates docs/specs/STATUS.md from the specs and the traceability.

`--check` (gate `status-fresh`) fails if the committed file is out of date.
"""

from __future__ import annotations

import sys
from pathlib import Path

from lib.repo import root_from_args
from lib.specs import SPECS_DIR, derive_status, load_specs, normalize
from traceability import trace_coverage

STATUS_FILE = f"{SPECS_DIR}/STATUS.md"


def render_status(root: Path) -> str:
    specs = load_specs(root)
    covered = set(trace_coverage(root, specs).refs)
    lines = [
        "<!-- GENERATED by scripts/status.py. Do not edit by hand: run `python scripts/status.py`. -->",
        "# Spec status",
        "",
        "States: see [docs/workflow.md](../workflow.md#spec-states).",
        "",
    ]
    if not specs:
        lines.append("_No specs yet._")
    else:
        lines += ["| Spec | Title | State | AC with test | Tasks |", "|---|---|---|---|---|"]
        for spec in specs:
            tasks = f"{sum(t.done for t in spec.tasks)}/{len(spec.tasks)}" if spec.tasks is not None else "—"
            acs = f"{sum(a.id in covered for a in spec.acs)}/{len(spec.acs)}"
            title = spec.meta_str("title") or "?"
            lines.append(
                f"| [{spec.dir_id or spec.dir_name}]({spec.dir_name}/spec.md) | {title} "
                f"| {derive_status(spec, covered)} | {acs} | {tasks} |"
            )
    return "\n".join(lines) + "\n"


def main(argv: list[str]) -> int:
    root = root_from_args(argv)
    file = root / STATUS_FILE
    nxt = render_status(root)
    if "--check" in argv:
        current = normalize(file.read_text(encoding="utf-8")) if file.exists() else ""
        if current != nxt:
            print(f"[FAIL] {STATUS_FILE} is out of date: run python scripts/status.py")
            return 1
        print("status-fresh: ok")
        return 0
    file.parent.mkdir(parents=True, exist_ok=True)
    file.write_text(nxt, encoding="utf-8", newline="\n")
    print(nxt)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
